insert into public.exercises (code, name_es, muscle_group, equipment, level, instructions, common_mistakes) values
  ('push_up', 'Flexiones de pecho', 'chest', 'bodyweight', 'beginner', 'Manos un poco más abiertas que los hombros, cuerpo recto de cabeza a talones. Baja el pecho hasta casi tocar el suelo con los codos a unos 45° del cuerpo y empuja hasta estirar los brazos.', 'Cadera caída o levantada; codos abiertos a 90°; recorrido incompleto.'),
  ('knee_push_up', 'Flexiones con rodillas apoyadas', 'chest', 'bodyweight', 'beginner', 'Igual que la flexión normal pero apoyando las rodillas. Mantén recta la línea de rodillas a cabeza y baja con control.', 'Doblar la cadera; mirar hacia adelante y arquear el cuello.'),
  ('incline_push_up', 'Flexiones inclinadas', 'chest', 'bodyweight', 'beginner', 'Manos sobre un banco, mesa o pared. Cuanto más alta la superficie, más fácil. Cuerpo recto, baja el pecho hacia el borde y empuja.', 'Usar una superficie inestable; perder la línea del cuerpo.'),
  ('diamond_push_up', 'Flexiones diamante', 'arms', 'bodyweight', 'intermediate', 'Manos juntas bajo el pecho formando un rombo con pulgares e índices. Codos pegados al cuerpo al bajar. Trabaja más el tríceps.', 'Abrir los codos hacia afuera; hundir los hombros.'),
  ('pike_push_up', 'Flexiones en pica', 'shoulders', 'bodyweight', 'intermediate', 'Cadera alta formando una V invertida. Dobla los codos para llevar la cabeza hacia el suelo entre las manos y empuja de vuelta.', 'Bajar la cadera durante la repetición; codos muy abiertos.'),
  ('dip', 'Fondos en paralelas', 'chest', 'dip_bars', 'intermediate', 'Sujétate con brazos estirados. Baja doblando los codos hasta que los hombros queden un poco por debajo de los codos, inclinando el torso levemente, y sube.', 'Bajar demasiado con dolor de hombro; balancear las piernas.'),
  ('bench_dip', 'Fondos en banco', 'arms', 'bench', 'beginner', 'Manos en el borde de un banco detrás de ti, piernas al frente. Baja doblando los codos hasta unos 90° y empuja.', 'Alejar la espalda del banco; encoger los hombros hacia las orejas.'),
  ('pull_up', 'Dominadas', 'back', 'pullup_bar', 'intermediate', 'Cuélgate con agarre prono algo más ancho que los hombros. Lleva los omóplatos hacia abajo y sube hasta pasar la barbilla sobre la barra. Baja controlado hasta estirar los brazos.', 'Balancearse; medio recorrido; subir solo con el cuello.'),
  ('chin_up', 'Dominadas supinas', 'back', 'pullup_bar', 'intermediate', 'Agarre con las palmas hacia ti, al ancho de hombros. Sube hasta pasar la barbilla y baja con control.', 'Impulsarse con las piernas; no estirar los brazos abajo.'),
  ('negative_pull_up', 'Dominadas negativas', 'back', 'pullup_bar', 'beginner', 'Sube a la posición alta con un salto o un banco y baja lo más lento posible (3–5 segundos) hasta colgar con brazos estirados.', 'Dejarse caer rápido; bajar sin tensión en la espalda.'),
  ('australian_row', 'Remo australiano', 'back', 'pullup_bar', 'beginner', 'Bajo una barra baja o mesa firme, cuerpo recto y talones en el suelo. Tira del pecho hacia la barra juntando los omóplatos y baja controlado.', 'Cadera caída; tirar solo con los brazos.'),
  ('dead_hang', 'Colgado pasivo', 'back', 'pullup_bar', 'beginner', 'Cuélgate de la barra con brazos estirados y respira con calma. Mantén el tiempo indicado.', 'Soltar antes por dolor en las manos sin descansar; encoger los hombros al máximo.'),
  ('dumbbell_row', 'Remo con mancuerna', 'back', 'dumbbells', 'beginner', 'Apoya una mano y una rodilla en un banco. Con la espalda plana, tira de la mancuerna hacia la cadera y baja controlado.', 'Girar el torso; redondear la espalda.'),
  ('dumbbell_press', 'Press de pecho con mancuernas', 'chest', 'dumbbells', 'beginner', 'Acostado en un banco, mancuernas a la altura del pecho. Empuja hacia arriba hasta casi juntarlas y baja con control.', 'Rebotar abajo; arquear exageradamente la espalda.'),
  ('shoulder_press', 'Press militar con mancuernas', 'shoulders', 'dumbbells', 'beginner', 'De pie o sentado, mancuernas a la altura de los hombros. Empuja hacia arriba sin arquear la zona lumbar y baja controlado.', 'Arquear la espalda; bloquear de golpe los codos.'),
  ('lateral_raise', 'Elevaciones laterales', 'shoulders', 'dumbbells', 'beginner', 'Brazos a los lados con codos apenas doblados. Eleva hasta la altura de los hombros y baja lento.', 'Usar impulso; subir por encima de los hombros con encogimiento.'),
  ('bicep_curl', 'Curl de bíceps', 'arms', 'dumbbells', 'beginner', 'De pie, codos pegados al cuerpo. Flexiona hasta subir las mancuernas y baja controlado sin mover los codos.', 'Balancear el torso; mover los codos hacia adelante.'),
  ('squat', 'Sentadilla', 'legs', 'bodyweight', 'beginner', 'Pies al ancho de hombros. Baja llevando la cadera atrás y abajo con el pecho erguido hasta que los muslos queden paralelos al suelo, y sube empujando el piso.', 'Rodillas hacia adentro; talones que se levantan; espalda redondeada.'),
  ('jump_squat', 'Sentadilla con salto', 'legs', 'bodyweight', 'intermediate', 'Haz una sentadilla y sube con un salto explosivo. Aterriza suave con las rodillas dobladas y encadena la siguiente.', 'Aterrizar con piernas rígidas; rodillas hacia adentro.'),
  ('lunge', 'Zancadas', 'legs', 'bodyweight', 'beginner', 'Da un paso largo y baja hasta que ambas rodillas formen unos 90°. Empuja con la pierna de adelante para volver. Alterna piernas.', 'Rodilla de adelante que pasa mucho la punta del pie; torso inclinado.'),
  ('bulgarian_split_squat', 'Sentadilla búlgara', 'legs', 'bench', 'intermediate', 'Pie trasero apoyado en un banco. Baja con la pierna delantera hasta que el muslo quede casi paralelo al suelo y sube.', 'Pie delantero demasiado cerca del banco; perder el equilibrio por ir rápido.'),
  ('glute_bridge', 'Puente de glúteos', 'glutes', 'bodyweight', 'beginner', 'Boca arriba, rodillas dobladas y pies en el suelo. Eleva la cadera apretando los glúteos hasta formar una línea de rodillas a hombros y baja.', 'Arquear la zona lumbar; empujar con la punta de los pies.'),
  ('calf_raise', 'Elevación de talones', 'legs', 'bodyweight', 'beginner', 'De pie, sube sobre la punta de los pies lo más alto posible, sostén un segundo y baja lento.', 'Rebotar; hacer el recorrido incompleto.'),
  ('goblet_squat', 'Sentadilla goblet', 'legs', 'dumbbells', 'beginner', 'Sostén una mancuerna o pesa rusa frente al pecho. Baja en sentadilla con el pecho erguido y sube.', 'Dejar caer el pecho hacia adelante; rodillas hacia adentro.'),
  ('kettlebell_swing', 'Swing con pesa rusa', 'full_body', 'kettlebell', 'intermediate', 'Con la pesa entre las piernas, empuja la cadera hacia adelante con fuerza para llevarla a la altura del pecho. La fuerza sale de la cadera, no de los brazos.', 'Hacer una sentadilla en lugar de bisagra de cadera; tirar con los brazos.'),
  ('plank', 'Plancha', 'core', 'bodyweight', 'beginner', 'Antebrazos bajo los hombros y cuerpo recto. Aprieta abdomen y glúteos y mantén el tiempo indicado respirando con normalidad.', 'Cadera caída o muy alta; contener la respiración.'),
  ('side_plank', 'Plancha lateral', 'core', 'bodyweight', 'beginner', 'Apoyado en un antebrazo y el borde del pie, cuerpo en línea recta. Mantén la cadera arriba. Cambia de lado.', 'Dejar caer la cadera; girar el torso.'),
  ('hollow_hold', 'Hollow hold', 'core', 'bodyweight', 'intermediate', 'Boca arriba, zona lumbar pegada al suelo, eleva brazos y piernas estirados formando una curva. Mantén la posición.', 'Despegar la zona lumbar; contener la respiración.'),
  ('hanging_knee_raise', 'Elevación de rodillas colgado', 'core', 'pullup_bar', 'intermediate', 'Colgado de la barra, sube las rodillas hacia el pecho con control y baja sin balancearte.', 'Balancearse para subir; bajar de golpe.'),
  ('mountain_climber', 'Escaladores', 'cardio', 'bodyweight', 'beginner', 'En posición de plancha alta, lleva las rodillas al pecho alternando con ritmo, manteniendo la cadera baja.', 'Levantar la cadera; perder la alineación de hombros sobre manos.'),
  ('burpee', 'Burpees', 'full_body', 'bodyweight', 'intermediate', 'De pie, baja a apoyar las manos, salta atrás a plancha, haz una flexión opcional, vuelve los pies a las manos y salta arriba.', 'Cadera caída en la plancha; aterrizar con rodillas rígidas.'),
  ('jumping_jack', 'Saltos de tijera', 'cardio', 'bodyweight', 'beginner', 'Salta abriendo piernas y brazos a la vez y vuelve a cerrar. Mantén un ritmo constante.', 'Aterrizar sobre los talones; encoger los hombros.'),
  ('jump_rope', 'Saltar la soga', 'cardio', 'jump_rope', 'beginner', 'Saltos cortos sobre la punta de los pies, girando la soga con las muñecas y los codos cerca del cuerpo.', 'Saltar demasiado alto; girar con los hombros.'),
  ('shadow_boxing', 'Sombra de boxeo', 'cardio', 'bodyweight', 'beginner', 'En guardia, lanza combinaciones al aire (jab, recto, gancho) moviendo los pies. Vuelve siempre a la guardia.', 'Bajar las manos; estirar el codo hasta trabarlo.'),
  ('heavy_bag_rounds', 'Rounds en saco', 'cardio', 'punching_bag', 'intermediate', 'Golpea el saco por rounds con combinaciones, moviéndote alrededor. Usa vendas y guantes. Descansa entre rounds.', 'Golpear sin vendas; mantener los pies quietos; perder la guardia.'),
  ('band_pull_apart', 'Aperturas con banda', 'shoulders', 'bands', 'beginner', 'Sostén una banda frente a ti con brazos estirados. Sepárala llevando las manos a los lados juntando los omóplatos, y vuelve lento.', 'Encoger los hombros; doblar mucho los codos.'),
  ('superman', 'Superman', 'back', 'bodyweight', 'beginner', 'Boca abajo, eleva a la vez brazos, pecho y piernas unos centímetros, sostén un segundo y baja.', 'Levantar demasiado el cuello; hacerlo con impulso.'),
  ('barbell_back_squat', 'Sentadilla con barra', 'legs', 'barbell', 'intermediate', 'Barra apoyada sobre la parte alta de la espalda, pies al ancho de hombros y puntas un poco hacia afuera. Toma aire, aprieta el abdomen y baja sentándote hacia atrás hasta que los muslos queden paralelos al suelo o un poco más. Sube empujando el suelo con todo el pie.', 'Rodillas que se van hacia adentro; levantar los talones; redondear la espalda baja al final del recorrido.'),
  ('barbell_bench_press', 'Press de banca con barra', 'chest', 'barbell', 'intermediate', 'Acostado en el banco con los ojos bajo la barra, pies firmes en el suelo y omóplatos juntos. Baja la barra con control hasta la parte baja del pecho, codos a unos 45°, y empuja hasta estirar los brazos. Usa siempre topes o un compañero que te asista.', 'Rebotar la barra en el pecho; despegar la cadera del banco; abrir los codos a 90°.'),
  ('barbell_deadlift', 'Peso muerto con barra', 'full_body', 'barbell', 'advanced', 'Barra sobre la mitad del pie, agárrala por fuera de las rodillas. Espalda neutra, pecho arriba y hombros ligeramente delante de la barra. Empuja el suelo con las piernas y extiende la cadera manteniendo la barra pegada al cuerpo. Baja con el mismo control.', 'Redondear la espalda; tirar con los brazos; alejar la barra de las piernas; hiperextender la espalda arriba.'),
  ('barbell_row', 'Remo con barra', 'back', 'barbell', 'intermediate', 'De pie, inclina el torso unos 45° desde la cadera con la espalda recta y rodillas un poco flexionadas. Tira la barra hacia el ombligo juntando los omóplatos y bájala con control.', 'Usar impulso con el torso; encoger los hombros; redondear la espalda.'),
  ('overhead_press', 'Press militar con barra', 'shoulders', 'barbell', 'intermediate', 'De pie, barra a la altura de las clavículas y manos un poco más abiertas que los hombros. Aprieta glúteos y abdomen y empuja la barra en línea recta sobre la cabeza, pasando la cara hacia atrás. Baja con control.', 'Arquear la espalda baja; empujar la barra hacia adelante en vez de hacia arriba.'),
  ('romanian_deadlift', 'Peso muerto rumano con mancuernas', 'glutes', 'dumbbells', 'beginner', 'De pie con una mancuerna en cada mano. Con las rodillas apenas flexionadas, lleva la cadera hacia atrás y baja las pesas cerca de las piernas hasta sentir estiramiento en la parte posterior del muslo. Vuelve a subir apretando los glúteos.', 'Doblar demasiado las rodillas; redondear la espalda; bajar más allá de donde mantienes la espalda recta.'),
  ('lat_pulldown', 'Jalón al pecho en polea', 'back', 'machines', 'beginner', 'Sentado con los muslos sujetos, toma la barra un poco más abierta que los hombros. Lleva el pecho ligeramente hacia arriba y tira la barra hasta la parte alta del pecho bajando los codos. Sube con control.', 'Tirar detrás de la nuca; balancear el torso; dejar subir la barra de golpe.'),
  ('leg_press', 'Prensa de piernas', 'legs', 'machines', 'beginner', 'Espalda y cadera apoyadas en el respaldo, pies al ancho de hombros en la plataforma. Quita los seguros, baja la plataforma flexionando las rodillas hasta unos 90° y empuja sin bloquear del todo las rodillas.', 'Despegar la cadera del asiento; bloquear las rodillas arriba; bajar tanto que se redondee la espalda baja.'),
  ('seated_cable_row', 'Remo sentado en polea', 'back', 'machines', 'beginner', 'Sentado con los pies apoyados y rodillas un poco flexionadas. Con la espalda recta, tira el agarre hacia el abdomen juntando los omóplatos y regresa estirando los brazos sin encorvarte.', 'Balancear el torso hacia atrás; encoger los hombros; redondear la espalda al volver.'),
  ('machine_chest_press', 'Press de pecho en máquina', 'chest', 'machines', 'beginner', 'Ajusta el asiento para que los agarres queden a la altura del pecho. Espalda apoyada, empuja hasta estirar los brazos sin bloquear los codos y regresa lento.', 'Despegar la espalda del respaldo; usar un recorrido demasiado corto.'),
  ('leg_curl', 'Curl femoral en máquina', 'legs', 'machines', 'beginner', 'Ajusta la máquina para que el rodillo quede sobre los tobillos. Flexiona las rodillas llevando los talones hacia los glúteos y vuelve despacio.', 'Levantar la cadera; hacer el movimiento con impulso; no controlar la bajada.')
